@RestController
@RequestMapping("/api/users")
public class UserController {

    private final UserRepository userRepository;

    public UserController(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    @GetMapping("/{id}")
    public User getUser(@PathVariable Long id) {
        return userRepository.findById(id)
            .orElseThrow(() -> new ResourceNotFoundException("User not found")); // Jackson serializes User to JSON
    }

    @PostMapping
    public User createUser(@RequestBody User user) { // @RequestBody deserializes JSON to User
        return userRepository.save(user); // Return value becomes JSON automatically
    }
}

@RestController
@RequestMapping("/api/products")
public class ProductController {

    private final ProductService productService;

    public ProductController(ProductService productService) {
        this.productService = productService;
    }

    @GetMapping("/{id}")
    public Product getProduct(@PathVariable Long id) { // Idempotent: safe to retry
        return productService.findById(id);
    }

    @PostMapping
    public Product createProduct(@RequestBody Product product) { // NOT idempotent: retrying creates duplicates
        return productService.create(product);
    }

    @PutMapping("/{id}")
    public Product updateProduct(@PathVariable Long id, @RequestBody Product product) { // Idempotent: same result on repeat
        return productService.replace(id, product);
    }

    @PatchMapping("/{id}")
    public Product patchProduct(@PathVariable Long id, @RequestBody Map<String, Object> updates) { // Partial update
        return productService.partialUpdate(id, updates);
    }

    @DeleteMapping("/{id}")
    public void deleteProduct(@PathVariable Long id) { // Idempotent: deleting twice has same effect
        productService.delete(id);
    }
}

record User(Long id, String firstName, String email, LocalDateTime createdAt) {} // Java 17 record

@RestController
@RequestMapping("/api/users")
public class UserController {

    @GetMapping("/{id}")
    public User getUser(@PathVariable Long id) {
        var user = new User(1L, "Alice", "alice@example.com", LocalDateTime.now());
        return user; // Jackson serializes this to JSON automatically
    }

    @PostMapping
    public User createUser(@RequestBody User user) { // Jackson deserializes JSON to User object
        return user;
    }
}

