@ResponseStatus(HttpStatus.NOT_FOUND) // Maps exception to 404 everywhere
public class ResourceNotFoundException extends RuntimeException {
    public ResourceNotFoundException(String message) {
        super(message);
    }
}

@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private final OrderRepository orderRepository;

    public OrderController(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED) // Returns 201 instead of default 200
    public Order createOrder(@RequestBody Order order) {
        return orderRepository.save(order);
    }

    @GetMapping("/{id}")
    public Order getOrder(@PathVariable Long id) {
        return orderRepository.findById(id)
            .orElseThrow(() -> new ResourceNotFoundException("Order not found")); // Automatic 404 response
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT) // Returns 204, signals successful deletion with no body
    public void deleteOrder(@PathVariable Long id) {
        orderRepository.deleteById(id);
    }
}

@RestController
@RequestMapping("/api/users") // Base path for all methods
public class UserController {

    @GetMapping // Endpoint: GET /api/users
    public List<User> getAllUsers() {
        return List.of(new User(1L, "Alice"), new User(2L, "Bob"));
    }

    @GetMapping("/{id}") // Endpoint: GET /api/users/{id} (base + sub-path)
    public User getUserById(@PathVariable Long id) {
        return new User(id, "Alice");
    }

    @PostMapping // Endpoint: POST /api/users
    public User createUser(@RequestBody User user) {
        return user;
    }

    @GetMapping({"/search", "/find"}) // Multiple paths: GET /api/users/search OR /api/users/find
    public List<User> searchUsers(@RequestParam String name) {
        return List.of(new User(1L, name));
    }
}

record User(Long id, String name) {}

@RestController
@RequestMapping("/api/orders")
@CrossOrigin(origins = "http://localhost:3000") // Class-level: applies to all methods
public class OrderController {

    @GetMapping
    public List<Order> getAllOrders() {
        return List.of(
            new Order(1L, "Laptop", 899.99),
            new Order(2L, "Mouse", 29.99)
        );
    }

    @PostMapping
    @CrossOrigin(origins = {"http://localhost:3000", "https://prod.example.com"}) // Method-level override
    public Order createOrder(@RequestBody Order order) {
        // Spring adds Access-Control-Allow-Origin header to response
        return order;
    }
}

record Order(Long id, String item, Double price) {}
